-- WP-26: the verified_claims memo (02-database 7.6.5) and the wider ops_flags key check (per-agent pins, canaries,
-- shadows, kill switches and verifier_mode:<path>). Generated by drizzle-kit, then edited by hand:
--   1. CREATE TABLE -> CREATE UNLOGGED TABLE (drizzle-kit cannot express it): a crash empties the memo, which only
--      costs re-verification.
-- The key check is dropped and re-added wider in one transaction; every key the old code writes still passes.
CREATE UNLOGGED TABLE "verified_claims" (
	"claim_hash" "bytea" PRIMARY KEY NOT NULL,
	"verdict" text NOT NULL,
	"check_source" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"expires_at" timestamp with time zone NOT NULL,
	CONSTRAINT "verified_claims_hash_ck" CHECK (octet_length("verified_claims"."claim_hash") = 32),
	CONSTRAINT "verified_claims_verdict_ck" CHECK ("verified_claims"."verdict" in ('supported', 'unsupported', 'contradicted')),
	CONSTRAINT "verified_claims_source_ck" CHECK ("verified_claims"."check_source" in ('verifier', 'escalation')),
	CONSTRAINT "verified_claims_expiry_ck" CHECK ("verified_claims"."expires_at" > "verified_claims"."created_at" and "verified_claims"."expires_at" <= "verified_claims"."created_at" + interval '24 hours')
);
--> statement-breakpoint
ALTER TABLE "ops_flags" DROP CONSTRAINT "ops_flags_key_ck";--> statement-breakpoint
CREATE INDEX "verified_claims_expires_idx" ON "verified_claims" USING btree ("expires_at");--> statement-breakpoint
ALTER TABLE "ops_flags" ADD CONSTRAINT "ops_flags_key_ck" CHECK (key ~ '^(pause_cloud_apply|pause_scoring|llm_paused|approvals_frozen|cloud_applier_open|llm_shed_level|extension_only:(greenhouse|lever|ashby)|verifier_mode:(suggestions|tailor|drafts|prepare|patch)|(agent_disabled|prompt_pin|model_pin|prompt_canary|prompt_shadow):(resume-parser|jd-analyst|fit-scorer|resume-tailor|resume-writer|answer-drafter|cover-letter-writer|claim-verifier|claim-verifier-escalation|reply-classifier|outcome-analyst|interview-coach))$');